import{_ as i,o as e,c as a,an as s}from"./chunks/framework.bSPI6ch3.js";const c=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md","lastUpdated":null}'),r={name:"getting-started/index.md"};function n(o,t,l,h,d,p){return e(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started {#getting-started}&quot;">​</a></h1><p>The <a href="./../">home page</a> says what the package is for and shows the shortest fit that runs. The tutorials below go further.</p><h2 id="Installation" tabindex="-1">Installation <a class="header-anchor" href="#Installation" aria-label="Permalink to &quot;Installation {#Installation}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DistributionsInference&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Fitting needs a sampler and a chain type as well, and you choose both. The tutorials sample with <code>AdvancedMH</code> or <code>Turing</code> and hold the draws in <code>FlexiChains</code>.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AdvancedMH&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Turing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FlexiChains&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span></code></pre></div><p>Two tutorials ask for more. The custom-distribution page finds a maximum-a-posteriori point through <code>Bijectors</code> and <code>Optim</code>, and the composed-tree page needs <code>ComposedDistributions</code>.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bijectors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Optim&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ComposedDistributions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span></code></pre></div><h2 id="The-route-through-a-fit" tabindex="-1">The route through a fit <a class="header-anchor" href="#The-route-through-a-fit" aria-label="Permalink to &quot;The route through a fit {#The-route-through-a-fit}&quot;">​</a></h2><p>Every fit here is the same three steps, whatever the distribution and sampler.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Step</th><th style="text-align:right;">What you write</th><th style="text-align:right;">What it gives</th></tr></thead><tbody><tr><td style="text-align:right;">Declare</td><td style="text-align:right;"><a href="/previews/PR113/lib/public#DistributionsInference.parameter_rows"><code>parameter_rows</code></a> and <a href="/previews/PR113/lib/public#DistributionsInference.reconstruct"><code>reconstruct</code></a> on your type</td><td style="text-align:right;">one row per scalar parameter, and a way back from a flat vector</td></tr><tr><td style="text-align:right;">Score</td><td style="text-align:right;"><a href="/previews/PR113/lib/public#DistributionsInference.distribution_to_logdensity"><code>distribution_to_logdensity</code></a> or <a href="/previews/PR113/lib/public#DistributionsInference.distribution_to_turing"><code>distribution_to_turing</code></a></td><td style="text-align:right;">a <code>LogDensityProblems</code> problem, or a <code>DynamicPPL</code> model</td></tr><tr><td style="text-align:right;">Read back</td><td style="text-align:right;"><a href="/previews/PR113/lib/public#DistributionsInference.point_estimate"><code>point_estimate</code></a> or <a href="/previews/PR113/lib/public#DistributionsInference.distribution_draws"><code>distribution_draws</code></a></td><td style="text-align:right;">the fitted distribution</td></tr></tbody></table><p>Only the first step is written per type, and a distribution from a package that already implements the protocol skips it. A point estimate replaces the last two: <a href="/previews/PR113/lib/public#DistributionsInference.optimise_distribution"><code>optimise_distribution</code></a> takes the distribution, the data and an optimiser, and returns the fitted distribution.</p><h2 id="Tutorials" tabindex="-1">Tutorials <a class="header-anchor" href="#Tutorials" aria-label="Permalink to &quot;Tutorials {#Tutorials}&quot;">​</a></h2><ul><li><p><a href="/previews/PR113/getting-started/tutorials/custom-distribution#custom-distribution">Fitting a custom distribution</a> writes the protocol for a hand-rolled type, samples it with AdvancedMH, and finds a maximum-a-posteriori point with an external optimiser.</p></li><li><p><a href="/previews/PR113/getting-started/tutorials/turing#turing-sampling">Sampling with Turing</a> fits the same distribution as a <code>DynamicPPL</code> model and reads the chain back with the same two calls.</p></li><li><p><a href="/previews/PR113/getting-started/tutorials/composed-distributions#composed-distributions">Fitting a composed distribution</a> runs both routes against a <code>ComposedDistributions</code> tree, partial pooling included. Its extension writes the protocol methods.</p></li></ul><h2 id="Getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#Getting-help" aria-label="Permalink to &quot;Getting help {#Getting-help}&quot;">​</a></h2><p>For usage questions, ask on the <a href="https://discourse.julialang.org" target="_blank" rel="noreferrer">Julia Discourse</a> (the SciML or usage categories) or the <a href="https://community.epinowcast.org" target="_blank" rel="noreferrer">epinowcast community forum</a>, our home for epidemiological modelling questions. Please use <a href="https://github.com/EpiAware/DistributionsInference.jl/issues" target="_blank" rel="noreferrer">GitHub issues</a> for bug reports and feature requests only.</p><p>The layout, navigation, and infrastructure of this site are generated by <a href="https://epiawarepackagetools.epiaware.org" target="_blank" rel="noreferrer">EpiAwarePackageTools</a>. Its docs cover customising the generated pages and how template sync keeps this repository current.</p>`,17)])])}const g=i(r,[["render",n]]);export{c as __pageData,g as default};
